export const ACHIEVEMENTS=[{id:'first-finish',name:'On the board',detail:'Finish a race',reward:50,check:s=>s.gameMode==='race'&&s.won},{id:'clean-podium',name:'Clean podium',detail:'Podium without a car or rail hit',reward:125,check:s=>s.gameMode==='race'&&s.place<=3&&!s.impactCount&&!s.railHits},{id:'drift-driver',name:'Sideways',detail:'Bank three clean drifts in one run',reward:100,cosmetic:'drifter',check:s=>s.driftCount>=3},{id:'shortcut-scout',name:'Trailblazer',detail:'Complete a shortcut',reward:75,check:s=>s.shortcutsCompleted>0},{id:'endurance',name:'Long haul',detail:'Drive 5 km in Career',reward:150,check:s=>s.gameMode==='career'&&s.distance>=5000},{id:'airtime',name:'Frequent flyer',detail:'Take five ramps in one run',reward:75,check:s=>s.rampHits>=5}];
export function settleAchievements(profile,state){if(state.tutorial)return {reward:0,earned:[]};profile.achievements??=[];const earned=ACHIEVEMENTS.filter(a=>!profile.achievements.includes(a.id)&&a.check(state));let reward=0;for(const a of earned){profile.achievements.push(a.id);reward+=a.reward;if(a.cosmetic){profile.cosmeticUnlocks??=[];if(!profile.cosmeticUnlocks.includes(a.cosmetic))profile.cosmeticUnlocks.push(a.cosmetic);}}return {reward,earned:earned.map(a=>a.name)};}
export function medalFor(s){if(s.gameMode!=='race'||!s.won)return null;return s.place===1?'gold':s.place<=3?'silver':'bronze';}
